-- =====================================================================
-- 09_phan_tan.sql – Minh họa phân mảnh, định vị, nhân bản trên 3 site (sinh bởi gen_phantan.py)
-- Site k = database QLTV_CN0k. Quan hệ toàn cục = database QLTV.
-- Chạy sau build_all.sh. Cuối file kiểm tra 3 quy tắc: đầy đủ, tái thiết, tách biệt.
-- =====================================================================
SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;

-- ================= Site S1 = QLTV_CN01 =================
DROP DATABASE IF EXISTS QLTV_CN01;
CREATE DATABASE QLTV_CN01 CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
-- Nhân bản toàn phần các bảng danh mục (ít cập nhật, đọc ở mọi site)
CREATE TABLE QLTV_CN01.CHI_NHANH AS SELECT * FROM QLTV.CHI_NHANH;
CREATE TABLE QLTV_CN01.THE_LOAI AS SELECT * FROM QLTV.THE_LOAI;
CREATE TABLE QLTV_CN01.BANG_PHI_PHAT AS SELECT * FROM QLTV.BANG_PHI_PHAT;
CREATE TABLE QLTV_CN01.LOAI_PHONG AS SELECT * FROM QLTV.LOAI_PHONG;
CREATE TABLE QLTV_CN01.DAU_SACH AS SELECT * FROM QLTV.DAU_SACH;
CREATE TABLE QLTV_CN01.TAC_GIA AS SELECT * FROM QLTV.TAC_GIA;
CREATE TABLE QLTV_CN01.DAU_SACH_TAC_GIA AS SELECT * FROM QLTV.DAU_SACH_TAC_GIA;
-- Phân mảnh ngang nguyên thủy DOC_GIA theo minterm (MaChiNhanh, TrangThai)
CREATE TABLE QLTV_CN01.DOC_GIA_HD AS SELECT * FROM QLTV.DOC_GIA WHERE MaChiNhanh = 'CN01' AND TrangThai = 'HoatDong';
CREATE TABLE QLTV_CN01.DOC_GIA_KHOA AS SELECT * FROM QLTV.DOC_GIA WHERE MaChiNhanh = 'CN01' AND TrangThai = 'Khoa';
-- Phân mảnh lai NGUOI (phần độc giả): ngang dẫn xuất theo DOC_GIA_k, rồi dọc theo kết quả BEA
CREATE TABLE QLTV_CN01.NGUOI_DG_A AS SELECT MaNguoi, Ho, Dem, Ten, Email, LoaiNguoi FROM QLTV.NGUOI WHERE MaNguoi IN (SELECT MaNguoi FROM QLTV_CN01.DOC_GIA_HD UNION ALL SELECT MaNguoi FROM QLTV_CN01.DOC_GIA_KHOA);
CREATE TABLE QLTV_CN01.NGUOI_DG_B AS SELECT MaNguoi, NgaySinh, GioiTinh, SoNha, Phuong, Quan, TinhTP FROM QLTV.NGUOI WHERE MaNguoi IN (SELECT MaNguoi FROM QLTV_CN01.DOC_GIA_HD UNION ALL SELECT MaNguoi FROM QLTV_CN01.DOC_GIA_KHOA);
-- Phân mảnh ngang dẫn xuất (bán kết nối) theo DOC_GIA_k
CREATE TABLE QLTV_CN01.SDT_NGUOI_DG AS SELECT * FROM QLTV.SDT_NGUOI WHERE MaNguoi IN (SELECT MaNguoi FROM QLTV_CN01.DOC_GIA_HD UNION ALL SELECT MaNguoi FROM QLTV_CN01.DOC_GIA_KHOA);
CREATE TABLE QLTV_CN01.THE_DOC_GIA AS SELECT * FROM QLTV.THE_DOC_GIA WHERE MaDocGia IN (SELECT MaNguoi FROM QLTV_CN01.DOC_GIA_HD UNION ALL SELECT MaNguoi FROM QLTV_CN01.DOC_GIA_KHOA);
CREATE TABLE QLTV_CN01.PHIEU_MUON AS SELECT * FROM QLTV.PHIEU_MUON WHERE MaDocGia IN (SELECT MaNguoi FROM QLTV_CN01.DOC_GIA_HD UNION ALL SELECT MaNguoi FROM QLTV_CN01.DOC_GIA_KHOA);
CREATE TABLE QLTV_CN01.PHIEU_TRA AS SELECT * FROM QLTV.PHIEU_TRA WHERE MaDocGia IN (SELECT MaNguoi FROM QLTV_CN01.DOC_GIA_HD UNION ALL SELECT MaNguoi FROM QLTV_CN01.DOC_GIA_KHOA);
CREATE TABLE QLTV_CN01.CT_MUON AS SELECT * FROM QLTV.CT_MUON WHERE MaPhieuMuon IN (SELECT MaPhieuMuon FROM QLTV_CN01.PHIEU_MUON);
CREATE TABLE QLTV_CN01.PHIEU_PHAT AS SELECT * FROM QLTV.PHIEU_PHAT WHERE (MaPhieuMuon, MaCuonSach) IN (SELECT MaPhieuMuon, MaCuonSach FROM QLTV_CN01.CT_MUON);
-- Phân mảnh ngang nguyên thủy theo MaChiNhanh và dây chuyền dẫn xuất PHONG_KHO → GIA_SACH → CUON_SACH
CREATE TABLE QLTV_CN01.THU_THU AS SELECT * FROM QLTV.THU_THU WHERE MaChiNhanh = 'CN01';
CREATE TABLE QLTV_CN01.NGUOI_TT AS SELECT * FROM QLTV.NGUOI WHERE MaNguoi IN (SELECT MaNguoi FROM QLTV_CN01.THU_THU);
CREATE TABLE QLTV_CN01.SDT_NGUOI_TT AS SELECT * FROM QLTV.SDT_NGUOI WHERE MaNguoi IN (SELECT MaNguoi FROM QLTV_CN01.THU_THU);
CREATE TABLE QLTV_CN01.PHONG_KHO AS SELECT * FROM QLTV.PHONG_KHO WHERE MaChiNhanh = 'CN01';
CREATE TABLE QLTV_CN01.GIA_SACH AS SELECT * FROM QLTV.GIA_SACH WHERE MaPhongKho IN (SELECT MaPhongKho FROM QLTV_CN01.PHONG_KHO);
CREATE TABLE QLTV_CN01.CUON_SACH AS SELECT * FROM QLTV.CUON_SACH WHERE MaGia IN (SELECT MaGia FROM QLTV_CN01.GIA_SACH);
CREATE TABLE QLTV_CN01.PHONG_DOC AS SELECT * FROM QLTV.PHONG_DOC WHERE MaChiNhanh = 'CN01';
CREATE TABLE QLTV_CN01.PHIEU_THUE_PHONG AS SELECT * FROM QLTV.PHIEU_THUE_PHONG WHERE MaPhongDoc IN (SELECT MaPhongDoc FROM QLTV_CN01.PHONG_DOC);
-- Bảng lưu trữ (ít truy cập) chỉ đặt tại trụ sở S1, không phân mảnh
CREATE TABLE QLTV_CN01.SACH_THANH_LY AS SELECT * FROM QLTV.SACH_THANH_LY;
CREATE TABLE QLTV_CN01.CT_MUON_LUU_TRU AS SELECT * FROM QLTV.CT_MUON_LUU_TRU;
ALTER TABLE QLTV_CN01.DOC_GIA_HD ADD PRIMARY KEY (MaNguoi); ALTER TABLE QLTV_CN01.CUON_SACH ADD PRIMARY KEY (MaCuonSach); ALTER TABLE QLTV_CN01.CT_MUON ADD PRIMARY KEY (MaPhieuMuon, MaCuonSach);

