-- ================= Tái thiết quan hệ toàn cục từ các mảnh (lược đồ ánh xạ) =================
USE QLTV;
CREATE OR REPLACE VIEW pt_DOC_GIA AS SELECT * FROM QLTV_CN01.DOC_GIA_HD UNION ALL SELECT * FROM QLTV_CN01.DOC_GIA_KHOA UNION ALL SELECT * FROM QLTV_CN02.DOC_GIA_HD UNION ALL SELECT * FROM QLTV_CN02.DOC_GIA_KHOA UNION ALL SELECT * FROM QLTV_CN03.DOC_GIA_HD UNION ALL SELECT * FROM QLTV_CN03.DOC_GIA_KHOA;
CREATE OR REPLACE VIEW pt_NGUOI_DG AS SELECT a.MaNguoi, a.Ho, a.Dem, a.Ten, b.NgaySinh, b.GioiTinh, b.SoNha, b.Phuong, b.Quan, b.TinhTP, a.Email, a.LoaiNguoi FROM QLTV_CN01.NGUOI_DG_A a JOIN QLTV_CN01.NGUOI_DG_B b ON b.MaNguoi = a.MaNguoi UNION ALL SELECT a.MaNguoi, a.Ho, a.Dem, a.Ten, b.NgaySinh, b.GioiTinh, b.SoNha, b.Phuong, b.Quan, b.TinhTP, a.Email, a.LoaiNguoi FROM QLTV_CN02.NGUOI_DG_A a JOIN QLTV_CN02.NGUOI_DG_B b ON b.MaNguoi = a.MaNguoi UNION ALL SELECT a.MaNguoi, a.Ho, a.Dem, a.Ten, b.NgaySinh, b.GioiTinh, b.SoNha, b.Phuong, b.Quan, b.TinhTP, a.Email, a.LoaiNguoi FROM QLTV_CN03.NGUOI_DG_A a JOIN QLTV_CN03.NGUOI_DG_B b ON b.MaNguoi = a.MaNguoi;
CREATE OR REPLACE VIEW pt_PHIEU_MUON AS SELECT * FROM QLTV_CN01.PHIEU_MUON UNION ALL SELECT * FROM QLTV_CN02.PHIEU_MUON UNION ALL SELECT * FROM QLTV_CN03.PHIEU_MUON;
CREATE OR REPLACE VIEW pt_CT_MUON AS SELECT * FROM QLTV_CN01.CT_MUON UNION ALL SELECT * FROM QLTV_CN02.CT_MUON UNION ALL SELECT * FROM QLTV_CN03.CT_MUON;
CREATE OR REPLACE VIEW pt_PHIEU_TRA AS SELECT * FROM QLTV_CN01.PHIEU_TRA UNION ALL SELECT * FROM QLTV_CN02.PHIEU_TRA UNION ALL SELECT * FROM QLTV_CN03.PHIEU_TRA;
CREATE OR REPLACE VIEW pt_PHIEU_PHAT AS SELECT * FROM QLTV_CN01.PHIEU_PHAT UNION ALL SELECT * FROM QLTV_CN02.PHIEU_PHAT UNION ALL SELECT * FROM QLTV_CN03.PHIEU_PHAT;
CREATE OR REPLACE VIEW pt_CUON_SACH AS SELECT * FROM QLTV_CN01.CUON_SACH UNION ALL SELECT * FROM QLTV_CN02.CUON_SACH UNION ALL SELECT * FROM QLTV_CN03.CUON_SACH;
CREATE OR REPLACE VIEW pt_GIA_SACH AS SELECT * FROM QLTV_CN01.GIA_SACH UNION ALL SELECT * FROM QLTV_CN02.GIA_SACH UNION ALL SELECT * FROM QLTV_CN03.GIA_SACH;
CREATE OR REPLACE VIEW pt_THU_THU AS SELECT * FROM QLTV_CN01.THU_THU UNION ALL SELECT * FROM QLTV_CN02.THU_THU UNION ALL SELECT * FROM QLTV_CN03.THU_THU;
CREATE OR REPLACE VIEW pt_PHONG_DOC AS SELECT * FROM QLTV_CN01.PHONG_DOC UNION ALL SELECT * FROM QLTV_CN02.PHONG_DOC UNION ALL SELECT * FROM QLTV_CN03.PHONG_DOC;
CREATE OR REPLACE VIEW pt_PHIEU_THUE_PHONG AS SELECT * FROM QLTV_CN01.PHIEU_THUE_PHONG UNION ALL SELECT * FROM QLTV_CN02.PHIEU_THUE_PHONG UNION ALL SELECT * FROM QLTV_CN03.PHIEU_THUE_PHONG;
CREATE OR REPLACE VIEW pt_THE_DOC_GIA AS SELECT * FROM QLTV_CN01.THE_DOC_GIA UNION ALL SELECT * FROM QLTV_CN02.THE_DOC_GIA UNION ALL SELECT * FROM QLTV_CN03.THE_DOC_GIA;

-- ================= Kiểm tra 3 quy tắc phân mảnh =================
DROP TABLE IF EXISTS KIEM_TRA_PHAN_TAN;
CREATE TABLE KIEM_TRA_PHAN_TAN (QuanHe VARCHAR(30), QuyTac VARCHAR(20), GiaTri BIGINT, KyVong BIGINT, KetQua CHAR(4));
INSERT INTO KIEM_TRA_PHAN_TAN SELECT 'DOC_GIA', 'Day du', v, 0, IF(v = 0, 'PASS', 'FAIL') FROM (SELECT (SELECT COUNT(*) FROM (SELECT * FROM QLTV.DOC_GIA EXCEPT SELECT * FROM pt_DOC_GIA) d) AS v) x;
INSERT INTO KIEM_TRA_PHAN_TAN SELECT 'DOC_GIA', 'Tai thiet', v, 0, IF(v = 0, 'PASS', 'FAIL') FROM (SELECT (SELECT (SELECT COUNT(*) FROM pt_DOC_GIA) - (SELECT COUNT(*) FROM QLTV.DOC_GIA)) AS v) x;
INSERT INTO KIEM_TRA_PHAN_TAN SELECT 'DOC_GIA', 'Tach biet', v, 0, IF(v = 0, 'PASS', 'FAIL') FROM (SELECT (SELECT COUNT(*) FROM (SELECT MaNguoi FROM pt_DOC_GIA GROUP BY MaNguoi HAVING COUNT(*) > 1) d) AS v) x;
INSERT INTO KIEM_TRA_PHAN_TAN SELECT 'PHIEU_MUON', 'Day du', v, 0, IF(v = 0, 'PASS', 'FAIL') FROM (SELECT (SELECT COUNT(*) FROM (SELECT * FROM QLTV.PHIEU_MUON EXCEPT SELECT * FROM pt_PHIEU_MUON) d) AS v) x;
INSERT INTO KIEM_TRA_PHAN_TAN SELECT 'PHIEU_MUON', 'Tai thiet', v, 0, IF(v = 0, 'PASS', 'FAIL') FROM (SELECT (SELECT (SELECT COUNT(*) FROM pt_PHIEU_MUON) - (SELECT COUNT(*) FROM QLTV.PHIEU_MUON)) AS v) x;
INSERT INTO KIEM_TRA_PHAN_TAN SELECT 'PHIEU_MUON', 'Tach biet', v, 0, IF(v = 0, 'PASS', 'FAIL') FROM (SELECT (SELECT COUNT(*) FROM (SELECT MaPhieuMuon FROM pt_PHIEU_MUON GROUP BY MaPhieuMuon HAVING COUNT(*) > 1) d) AS v) x;
INSERT INTO KIEM_TRA_PHAN_TAN SELECT 'CT_MUON', 'Day du', v, 0, IF(v = 0, 'PASS', 'FAIL') FROM (SELECT (SELECT COUNT(*) FROM (SELECT * FROM QLTV.CT_MUON EXCEPT SELECT * FROM pt_CT_MUON) d) AS v) x;
INSERT INTO KIEM_TRA_PHAN_TAN SELECT 'CT_MUON', 'Tai thiet', v, 0, IF(v = 0, 'PASS', 'FAIL') FROM (SELECT (SELECT (SELECT COUNT(*) FROM pt_CT_MUON) - (SELECT COUNT(*) FROM QLTV.CT_MUON)) AS v) x;
INSERT INTO KIEM_TRA_PHAN_TAN SELECT 'CT_MUON', 'Tach biet', v, 0, IF(v = 0, 'PASS', 'FAIL') FROM (SELECT (SELECT COUNT(*) FROM (SELECT MaPhieuMuon, MaCuonSach FROM pt_CT_MUON GROUP BY MaPhieuMuon, MaCuonSach HAVING COUNT(*) > 1) d) AS v) x;
INSERT INTO KIEM_TRA_PHAN_TAN SELECT 'PHIEU_TRA', 'Day du', v, 0, IF(v = 0, 'PASS', 'FAIL') FROM (SELECT (SELECT COUNT(*) FROM (SELECT * FROM QLTV.PHIEU_TRA EXCEPT SELECT * FROM pt_PHIEU_TRA) d) AS v) x;
INSERT INTO KIEM_TRA_PHAN_TAN SELECT 'PHIEU_TRA', 'Tai thiet', v, 0, IF(v = 0, 'PASS', 'FAIL') FROM (SELECT (SELECT (SELECT COUNT(*) FROM pt_PHIEU_TRA) - (SELECT COUNT(*) FROM QLTV.PHIEU_TRA)) AS v) x;
INSERT INTO KIEM_TRA_PHAN_TAN SELECT 'PHIEU_TRA', 'Tach biet', v, 0, IF(v = 0, 'PASS', 'FAIL') FROM (SELECT (SELECT COUNT(*) FROM (SELECT MaPhieuTra FROM pt_PHIEU_TRA GROUP BY MaPhieuTra HAVING COUNT(*) > 1) d) AS v) x;
INSERT INTO KIEM_TRA_PHAN_TAN SELECT 'PHIEU_PHAT', 'Day du', v, 0, IF(v = 0, 'PASS', 'FAIL') FROM (SELECT (SELECT COUNT(*) FROM (SELECT * FROM QLTV.PHIEU_PHAT EXCEPT SELECT * FROM pt_PHIEU_PHAT) d) AS v) x;
